package com.daniil.wristlens.wear;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.view.View;import android.widget.*;import androidx.work.*;import com.daniil.wristlens.shared.*;import org.json.*;import java.util.*;import java.util.function.BiConsumer;
/** Durable per-file download status, shared by workers, gallery and notification actions. */
final class Downloads {
 static final String QUEUED="queued",PREPARING="preparing",RUNNING="running",COMPLETE="complete",CANCELLED="cancelled",ERROR="error";
 static BiConsumer<Context,OneTimeWorkRequest> schedule=(c,w)->WorkManager.getInstance(c).enqueue(w);
 static BiConsumer<Context,UUID> cancelWork=(c,id)->WorkManager.getInstance(c).cancelWorkById(id);
 record State(String job,String phase,String name,long done,long total,int index,int count){boolean active(){return List.of(QUEUED,PREPARING,RUNNING).contains(phase);}}
 private static JSONObject all(Context c){try{return new JSONObject(c.getSharedPreferences("downloads",0).getString("jobs","{}"));}catch(JSONException e){return new JSONObject();}}
 private static void save(Context c,JSONObject j){if(!c.getSharedPreferences("downloads",0).edit().putString("jobs",j.toString()).commit())throw new IllegalStateException("Cannot save download state");}
 static synchronized JSONObject job(Context c,String id){return all(c).optJSONObject(id);}
 static synchronized State state(Context c,String node,String file){JSONObject jobs=all(c);State result=null;long newest=-1;for(Iterator<String> it=jobs.keys();it.hasNext();){String id=it.next();JSONObject j=jobs.optJSONObject(id);if(!node.equals(j.optString("node")))continue;JSONArray items=j.optJSONArray("items");for(int i=0;i<items.length();i++){JSONObject f=items.optJSONObject(i);if(file.equals(f.optString("id"))&&j.optLong("created")>=newest){result=new State(id,f.optString("phase"),f.optString("name"),f.optLong("done"),f.optLong("total"),i+1,items.length());newest=j.optLong("created");}}}return result;}
 static synchronized String create(Context c,String node,List<JSONObject> files,boolean automatic,UUID work){JSONObject jobs=all(c);JSONArray items=new JSONArray();for(JSONObject f:files){State old=state(c,node,f.optString("id"));if(old!=null&&old.active())continue;items.put(Wire.object("id",f.optString("id"),"name",f.optString("name"),"sequence",f.optLong("sequence"),"phase",QUEUED,"done",0,"total",f.optLong("bytes")));}if(items.length()==0)return "";long created=System.currentTimeMillis();for(Iterator<String> keys=jobs.keys();keys.hasNext();)created=Math.max(created,jobs.optJSONObject(keys.next()).optLong("created")+1);String id=UUID.randomUUID().toString();try{jobs.put(id,Wire.object("node",node,"work",work==null?"":work.toString(),"automatic",automatic,"created",created,"phase",QUEUED,"items",items));}catch(JSONException e){throw new IllegalStateException(e);}List<String> terminal=new ArrayList<>();jobs.keys().forEachRemaining(k->{if(!active(jobs.optJSONObject(k).optString("phase")))terminal.add(k);});terminal.sort(Comparator.comparingLong(k->jobs.optJSONObject(k).optLong("created")));for(int i=0;i<terminal.size()-30;i++)jobs.remove(terminal.get(i));save(c,jobs);return id;}
 private static boolean active(String phase){return List.of(QUEUED,PREPARING,RUNNING).contains(phase);}
 static synchronized void work(Context c,String id,UUID work){JSONObject a=all(c),j=a.optJSONObject(id);if(j==null)return;try{j.put("work",work.toString());save(c,a);}catch(JSONException e){throw new IllegalStateException(e);}}
 static synchronized void update(Context c,String id,String file,String phase,long done,long total,String name){JSONObject a=all(c),j=a.optJSONObject(id);if(j==null||CANCELLED.equals(j.optString("phase")))return;try{JSONArray fs=j.getJSONArray("items");for(int i=0;i<fs.length();i++){JSONObject f=fs.getJSONObject(i);if(!file.equals(f.optString("id")))continue;f.put("phase",phase).put("done",done);if(total>0)f.put("total",total);if(name!=null)f.put("name",name);j.put("phase",RUNNING).put("current",i);break;}save(c,a);}catch(JSONException e){throw new IllegalStateException(e);}}
 static synchronized void finish(Context c,String id,String phase){JSONObject a=all(c),j=a.optJSONObject(id);if(j==null||CANCELLED.equals(j.optString("phase")))return;try{j.put("phase",phase);JSONArray fs=j.getJSONArray("items");for(int i=0;i<fs.length();i++){JSONObject f=fs.getJSONObject(i);if(!COMPLETE.equals(f.optString("phase")))f.put("phase",phase);}save(c,a);}catch(JSONException e){throw new IllegalStateException(e);}}
 static boolean cancelled(Context c,String id){JSONObject j=job(c,id);return j==null||CANCELLED.equals(j.optString("phase"));}
 static String enqueue(Activity a,String node,List<JSONObject> files){String id=create(a,node,files,false,null);if(id.isEmpty())return id;OneTimeWorkRequest work=new OneTimeWorkRequest.Builder(DownloadWorker.class).setInputData(new Data.Builder().putString("job",id).build()).build();work(a,id,work.getId());schedule.accept(a.getApplicationContext(),work);Controls.notice(a,Strings.tr(com.daniil.wristlens.shared.R.string.download_started));if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},90);return id;}
 static void cancel(Context c,String id){JSONObject j=job(c,id);if(j==null||!active(j.optString("phase")))return;finish(c,id,CANCELLED);String work=j.optString("work");if(!work.isEmpty())cancelWork.accept(c,UUID.fromString(work));if(j.optBoolean("automatic")){JSONArray items=j.optJSONArray("items");JSONObject f=items==null?null:items.optJSONObject(j.optInt("current"));if(f!=null){SharedPreferences p=AutoSave.prefs(c);p.edit().putLong("cursor",Math.max(p.getLong("cursor",0),f.optLong("sequence"))).apply();}}c.getSystemService(NotificationManager.class).cancel(notificationId(c,id));Controls.notice(c,Strings.tr(com.daniil.wristlens.shared.R.string.download_cancelled));}
 static int notificationId(Context c,String id){JSONObject j=job(c,id);return j!=null&&j.optBoolean("automatic")?41:1000+(id.hashCode()&0x3fffffff);}
 static State current(Context c,String id){JSONObject j=job(c,id);if(j==null)return new State(id,ERROR,"",0,0,1,1);JSONArray fs=j.optJSONArray("items");int i=Math.min(j.optInt("current"),fs.length()-1);JSONObject f=fs.optJSONObject(i);return new State(id,f.optString("phase"),f.optString("name"),f.optLong("done"),f.optLong("total"),i+1,fs.length());}
 static String label(State s){if(s==null)return "";return switch(s.phase){case QUEUED->Strings.tr(com.daniil.wristlens.shared.R.string.download_queued);case PREPARING->Strings.tr(com.daniil.wristlens.shared.R.string.copy_preparing);case RUNNING->String.format(Locale.getDefault(),Strings.tr(com.daniil.wristlens.shared.R.string.download_running),percent(s));case COMPLETE->Strings.tr(com.daniil.wristlens.shared.R.string.copy_downloaded);case CANCELLED->Strings.tr(com.daniil.wristlens.shared.R.string.download_cancelled);default->Strings.tr(com.daniil.wristlens.shared.R.string.download_failed);};}
 static int percent(State s){return s.total<=0?0:(int)Math.min(100,s.done*100/s.total);}
 static ForegroundInfo foreground(Context c,String id){State s=current(c,id);NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("originals",Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_00),NotificationManager.IMPORTANCE_LOW));int nid=notificationId(c,id);PendingIntent cancel=PendingIntent.getBroadcast(c,nid,new Intent(c,DownloadCancelReceiver.class).setAction("cancel:"+id).putExtra("job",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,WatchActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String text=label(s)+" · "+String.format(Locale.getDefault(),Strings.tr(com.daniil.wristlens.shared.R.string.download_batch),s.index,s.count);Notification n=new Notification.Builder(c,"originals").setSmallIcon(R.drawable.ic_camera).setContentTitle(s.name.isEmpty()?"WristLens":s.name).setContentText(text).setSubText("WristLens").setContentIntent(open).setOnlyAlertOnce(true).setOngoing(true).setProgress(100,percent(s),!RUNNING.equals(s.phase)||s.total<=0).addAction(new Notification.Action.Builder(null,Strings.tr(com.daniil.wristlens.shared.R.string.download_cancel),cancel).build()).build();return new ForegroundInfo(nid,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC);}
 static void notify(Context c,String id){if(cancelled(c,id))return;ForegroundInfo f=foreground(c,id);c.getSystemService(NotificationManager.class).notify(f.getNotificationId(),f.getNotification());}
 static void bind(TextView view,String node,String file,Button save,Button cancel){Handler h=new Handler(Looper.getMainLooper());Runnable tick=new Runnable(){public void run(){if(!view.isAttachedToWindow())return;State s=state(view.getContext(),node,file);view.setText(label(s));view.setVisibility(s==null?View.GONE:View.VISIBLE);boolean active=s!=null&&s.active();if(save!=null)save.setEnabled(!active);if(cancel!=null){cancel.setVisibility(active?View.VISIBLE:View.GONE);cancel.setOnClickListener(v->{ActionFeedback.press(v);Downloads.cancel(v.getContext(),s.job);});}h.postDelayed(this,500);}};view.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){h.post(tick);}public void onViewDetachedFromWindow(View v){h.removeCallbacks(tick);}});if(view.isAttachedToWindow())h.post(tick);}
}
